[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Aid Alliance — Together We Respond</title>
<meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
<style>
/* ── Reset & Base ── */
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Inter',system-ui,-apple-system,sans-serif;color:#1f2937;background:#fff;line-height:1.6;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{cursor:pointer;font-family:inherit;border:none;background:none}
ul{list-style:none}
h1,h2,h3{line-height:1.2}

/* ── Colors ── */
:root{
  --red:#C41E3A;--red-dark:#99162d;--red-light:#fde8ec;
  --navy:#1B3A5C;--navy-light:#2b5a8a;
  --white:#fff;
  --gray-50:#f9fafb;--gray-100:#f3f4f6;--gray-200:#e5e7eb;
  --gray-300:#d1d5db;--gray-400:#9ca3af;--gray-500:#6b7280;
  --gray-600:#4b5563;--gray-700:#374151;--gray-800:#1f2937;--gray-900:#111827;
}

/* ── Utility Bar ── */
.utility-bar{background:var(--navy);color:#fff;font-size:.8rem;padding:.375rem 0}
.utility-bar .container{display:flex;justify-content:flex-end;align-items:center;gap:1.25rem}
.utility-bar a{transition:opacity .2s}
.utility-bar a:hover{opacity:.75}

/* ── Header ── */
.site-header{position:sticky;top:0;z-index:50;background:var(--white);border-bottom:1px solid var(--gray-200);box-shadow:0 1px 3px rgba(0,0,0,.04)}
.site-header .container{display:flex;align-items:center;justify-content:space-between;padding-top:.875rem;padding-bottom:.875rem}
.logo{display:flex;align-items:center;gap:.625rem;font-weight:700;font-size:1.125rem;color:var(--navy);letter-spacing:-.01em}
.logo-icon{width:2rem;height:2rem;background:var(--red);border-radius:8px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800;font-size:1rem;flex-shrink:0}
.main-nav{display:flex;align-items:center;gap:1.75rem}
.main-nav a{font-size:.875rem;font-weight:500;color:var(--gray-700);transition:color .2s;white-space:nowrap}
.main-nav a:hover{color:var(--red)}
.btn{display:inline-flex;align-items:center;justify-content:center;padding:.625rem 1.375rem;font-weight:600;font-size:.875rem;border-radius:8px;transition:all .2s;white-space:nowrap}
.btn-primary{background:var(--red);color:#fff}
.btn-primary:hover{background:var(--red-dark)}
.btn-outline{border:2px solid var(--red);color:var(--red)}
.btn-outline:hover{background:var(--red);color:#fff}
.btn-white{background:var(--white);color:var(--navy)}
.btn-white:hover{background:var(--gray-100)}
.btn-large{padding:.75rem 2rem;font-size:1rem}
.hamburger{display:none;flex-direction:column;gap:5px;padding:4px;z-index:60}
.hamburger span{display:block;width:24px;height:2.5px;background:var(--gray-800);border-radius:2px;transition:all .3s}
.hamburger.active span:nth-child(1){transform:rotate(45deg) translate(5px,5px)}
.hamburger.active span:nth-child(2){opacity:0}
.hamburger.active span:nth-child(3){transform:rotate(-45deg) translate(5px,-5px)}

/* ── Mobile Nav ── */
.mobile-nav{position:fixed;top:0;right:-100%;width:280px;height:100vh;background:var(--white);z-index:55;padding:5rem 1.5rem 2rem;transition:right .3s ease;box-shadow:-4px 0 20px rgba(0,0,0,.12);display:flex;flex-direction:column;gap:.5rem;overflow-y:auto}
.mobile-nav.open{right:0}
.mobile-nav a{display:block;padding:.75rem 0;font-size:1rem;font-weight:500;color:var(--gray-700);border-bottom:1px solid var(--gray-100)}
.mobile-nav .btn{margin-top:.5rem;text-align:center}
.mobile-overlay{position:fixed;inset:0;background:rgba(0,0,0,.4);z-index:54;opacity:0;pointer-events:none;transition:opacity .3s}
.mobile-overlay.show{opacity:1;pointer-events:auto}

/* ── Container ── */
.container{max-width:1180px;margin:0 auto;padding:0 1.5rem}

/* ── Hero ── */
.hero{position:relative;background:linear-gradient(135deg,var(--navy) 0%,#0d2135 50%,var(--red-dark) 100%);color:#fff;overflow:hidden;min-height:580px;display:flex;align-items:center}
.hero::before{content:'';position:absolute;inset:0;background:url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 800"><circle cx="200" cy="150" r="300" fill="rgba(255,255,255,.02)"/><circle cx="1000" cy="650" r="400" fill="rgba(196,30,58,.08)"/><circle cx="900" cy="100" r="200" fill="rgba(255,255,255,.015)"/></svg>');background-size:cover;pointer-events:none}
.hero .container{position:relative;z-index:1;padding-top:5rem;padding-bottom:5rem;display:grid;grid-template-columns:1fr 1fr;gap:3rem;align-items:center}
.hero-text{max-width:560px}
.hero-badge{display:inline-block;background:rgba(255,255,255,.12);color:#fff;font-size:.8rem;font-weight:600;padding:.375rem .875rem;border-radius:100px;margin-bottom:1.25rem;letter-spacing:.02em;backdrop-filter:blur(4px)}
.hero h1{font-size:clamp(2.25rem,5vw,3.5rem);font-weight:800;line-height:1.1;margin-bottom:1.25rem;letter-spacing:-.02em}
.hero h1 span{color:#ff8fa3}
.hero-subtitle{font-size:1.1rem;color:rgba(255,255,255,.82);line-height:1.6;margin-bottom:2rem}
.hero-actions{display:flex;gap:.875rem;flex-wrap:wrap}
.hero-visual{display:flex;align-items:center;justify-content:center}
.hero-card{background:rgba(255,255,255,.08);backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,.12);border-radius:16px;padding:2rem;text-align:center}
.hero-card .stat-big{font-size:2.5rem;font-weight:800;color:#ff8fa3;display:block;line-height:1}
.hero-card .stat-label{font-size:.8rem;color:rgba(255,255,255,.7);margin-top:.375rem}
.hero-card-grid{display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-top:1rem}

/* ── Section ── */
.section{padding:5rem 0}
.section-header{text-align:center;margin-bottom:3rem}
.section-label{font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--red);margin-bottom:.5rem}
.section-title{font-size:clamp(1.75rem,3vw,2.5rem);font-weight:800;color:var(--gray-900);margin-bottom:.75rem}
.section-subtitle{font-size:1.05rem;color:var(--gray-500);max-width:640px;margin:0 auto}

/* ── Mission ── */
.mission-grid{display:grid;grid-template-columns:1fr 1fr;gap:3rem;align-items:center}
.mission-text h3{font-size:1.5rem;font-weight:700;color:var(--navy);margin-bottom:1rem}
.mission-text p{color:var(--gray-600);line-height:1.75;margin-bottom:1rem}
.mission-principles{display:flex;gap:1rem;flex-wrap:wrap;margin-top:1.5rem}
.principle-chip{background:var(--red-light);color:var(--red-dark);font-size:.8rem;font-weight:600;padding:.375rem .875rem;border-radius:100px}
.mission-visual{display:grid;grid-template-columns:1fr 1fr;gap:.75rem}
.mission-img{aspect-ratio:4/3;background:var(--gray-100);border-radius:12px;display:flex;align-items:center;justify-content:center;color:var(--gray-400);font-size:.8rem;overflow:hidden}
.mission-img img{width:100%;height:100%;object-fit:cover}
.mission-img.span-row{grid-row:span 2;aspect-ratio:3/4}

/* ── Impact Stats ── */
.impact{background:var(--navy);color:#fff}
.impact .section-label{color:rgba(255,255,255,.7)}
.impact .section-title{color:#fff}
.impact .section-subtitle{color:rgba(255,255,255,.7)}
.stats-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1.5rem}
.stat-card{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:16px;padding:2rem 1.5rem;text-align:center;transition:transform .3s,background .3s}
.stat-card:hover{transform:translateY(-4px);background:rgba(255,255,255,.1)}
.stat-number{font-size:clamp(2rem,4vw,3rem);font-weight:800;color:var(--red);line-height:1;margin-bottom:.5rem}
.stat-card:nth-child(1) .stat-number{color:#ff8fa3}
.stat-card:nth-child(2) .stat-number{color:#fbbf24}
.stat-card:nth-child(3) .stat-number{color:#60a5fa}
.stat-card:nth-child(4) .stat-number{color:#34d399}
.stat-desc{font-size:.9rem;color:rgba(255,255,255,.75);line-height:1.4}
.stat-icon{font-size:1.75rem;margin-bottom:.75rem;display:block}

/* ── Programs Accordion ── */
.programs-grid{max-width:840px;margin:0 auto}
.accordion-item{border:1px solid var(--gray-200);border-radius:12px;margin-bottom:.75rem;overflow:hidden;background:var(--white);transition:box-shadow .3s}
.accordion-item:hover{box-shadow:0 2px 12px rgba(0,0,0,.06)}
.accordion-trigger{width:100%;display:flex;align-items:center;justify-content:space-between;padding:1.25rem 1.5rem;font-size:1.05rem;font-weight:600;color:var(--gray-800);text-align:left;transition:color .2s}
.accordion-trigger:hover{color:var(--red)}
.accordion-icon{width:1.5rem;height:1.5rem;display:flex;align-items:center;justify-content:center;border-radius:50%;background:var(--gray-100);transition:transform .3s,background .3s;flex-shrink:0}
.accordion-item.active .accordion-icon{transform:rotate(45deg);background:var(--red-light);color:var(--red)}
.accordion-content{max-height:0;overflow:hidden;transition:max-height .4s ease,padding .4s ease}
.accordion-item.active .accordion-content{max-height:300px}
.accordion-inner{padding:0 1.5rem 1.5rem;color:var(--gray-600);line-height:1.7}
.accordion-inner p{margin-bottom:.75rem}

/* ── Get Involved ── */
.involved{background:var(--gray-50)}
.involved-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.5rem}
.involved-card{background:var(--white);border:1px solid var(--gray-200);border-radius:16px;padding:2rem;text-align:center;transition:transform .3s,box-shadow .3s}
.involved-card:hover{transform:translateY(-4px);box-shadow:0 12px 40px rgba(0,0,0,.08)}
.involved-icon{width:3.5rem;height:3.5rem;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:1.5rem;margin:0 auto 1.25rem}
.involved-icon.volunteer{background:#fde8ec;color:var(--red)}
.involved-icon.fundraiser{background:#e8f0fa;color:var(--navy)}
.involved-icon.blood{background:#fef3c7;color:#d97706}
.involved-card h3{font-size:1.15rem;font-weight:700;color:var(--gray-900);margin-bottom:.625rem}
.involved-card p{font-size:.9rem;color:var(--gray-500);line-height:1.6;margin-bottom:1.5rem}

/* ── News Carousel ── */
.news-wrapper{position:relative;overflow:hidden}
.news-track{display:flex;transition:transform .5s ease}
.news-card{flex:0 0 calc(33.333% - 1rem);margin-right:1.5rem;background:var(--white);border:1px solid var(--gray-200);border-radius:16px;overflow:hidden;transition:box-shadow .3s}
.news-card:hover{box-shadow:0 8px 30px rgba(0,0,0,.08)}
.news-img{aspect-ratio:16/10;background:var(--gray-100);display:flex;align-items:center;justify-content:center;color:var(--gray-400);font-size:.8rem}
.news-body{padding:1.25rem 1.5rem 1.5rem}
.news-tag{display:inline-block;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--red);margin-bottom:.5rem}
.news-card h3{font-size:1.05rem;font-weight:700;color:var(--gray-900);margin-bottom:.5rem}
.news-card p{font-size:.875rem;color:var(--gray-500);line-height:1.6}
.carousel-controls{display:flex;align-items:center;justify-content:center;gap:1rem;margin-top:2rem}
.carousel-btn{width:2.75rem;height:2.75rem;border-radius:50%;border:2px solid var(--gray-300);display:flex;align-items:center;justify-content:center;color:var(--gray-600);font-size:1.1rem;transition:all .2s}
.carousel-btn:hover{border-color:var(--red);color:var(--red);background:var(--red-light)}
.carousel-btn:disabled{opacity:.35;cursor:default}
.carousel-dots{display:flex;gap:.375rem}
.carousel-dot{width:.5rem;height:.5rem;border-radius:50%;background:var(--gray-300);transition:background .3s}
.carousel-dot.active{background:var(--red);width:1.5rem;border-radius:100px}

/* ── Donate CTA ── */
.donate-cta{background:linear-gradient(135deg,var(--red) 0%,var(--red-dark) 100%);color:#fff;text-align:center}
.donate-cta .section-label{color:rgba(255,255,255,.8)}
.donate-cta .section-title{color:#fff}
.donate-cta .section-subtitle{color:rgba(255,255,255,.82)}
.donate-table{max-width:720px;margin:0 auto 2rem}
.donate-table table{width:100%;border-collapse:separate;border-spacing:0;background:rgba(255,255,255,.1);border-radius:12px;overflow:hidden;backdrop-filter:blur(4px)}
.donate-table th{font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:rgba(255,255,255,.7);padding:.875rem 1.25rem;text-align:left;border-bottom:1px solid rgba(255,255,255,.12)}
.donate-table td{font-size:.95rem;padding:.875rem 1.25rem;border-bottom:1px solid rgba(255,255,255,.08)}
.donate-table tr:last-child td{border-bottom:none}
.donate-table tr:hover td{background:rgba(255,255,255,.06)}
.donate-table .amount{font-weight:700;color:#fff}
.donate-trust{font-size:.85rem;color:rgba(255,255,255,.65);margin-top:1rem}

/* ── Footer ── */
.site-footer{background:var(--gray-900);color:rgba(255,255,255,.65);padding:4rem 0 2rem}
.footer-grid{display:grid;grid-template-columns:2fr repeat(4,1fr);gap:2rem;margin-bottom:3rem}
.footer-brand h4{font-size:1.1rem;font-weight:700;color:#fff;margin-bottom:.75rem}
.footer-brand p{font-size:.875rem;line-height:1.6;margin-bottom:1rem}
.social-links{display:flex;gap:.75rem}
.social-link{width:2.25rem;height:2.25rem;border-radius:8px;background:rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center;font-size:.85rem;transition:background .2s}
.social-link:hover{background:var(--red)}
.footer-col h4{font-size:.85rem;font-weight:700;color:#fff;margin-bottom:1rem;text-transform:uppercase;letter-spacing:.04em}
.footer-col a{display:block;font-size:.875rem;margin-bottom:.5rem;transition:color .2s}
.footer-col a:hover{color:#fff}
.footer-bottom{border-top:1px solid rgba(255,255,255,.1);padding-top:1.5rem;font-size:.8rem;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:.5rem}

/* ── Donate Modal ── */
.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:100;display:flex;align-items:center;justify-content:center;padding:1rem;opacity:0;pointer-events:none;transition:opacity .3s}
.modal-overlay.show{opacity:1;pointer-events:auto}
.modal{background:var(--white);border-radius:20px;width:100%;max-width:520px;max-height:90vh;overflow-y:auto;box-shadow:0 25px 80px rgba(0,0,0,.25)}
.modal-header{display:flex;align-items:center;justify-content:space-between;padding:1.5rem 2rem;border-bottom:1px solid var(--gray-200)}
.modal-header h2{font-size:1.25rem;font-weight:700;color:var(--gray-900)}
.modal-close{width:2.25rem;height:2.25rem;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:1.25rem;color:var(--gray-500);transition:all .2s}
.modal-close:hover{background:var(--gray-100);color:var(--gray-800)}
.modal-body{padding:2rem}
.donate-amounts{display:grid;grid-template-columns:repeat(3,1fr);gap:.75rem;margin-bottom:2rem}
.donate-amount{position:relative;padding:1rem;border:2px solid var(--gray-200);border-radius:12px;text-align:center;font-weight:600;font-size:.95rem;color:var(--gray-700);transition:all .2s}
.donate-amount:hover{border-color:var(--red);color:var(--red)}
.donate-amount.selected{border-color:var(--red);background:var(--red-light);color:var(--red)}
.donate-amount .impact-text{display:block;font-size:.7rem;font-weight:400;color:var(--gray-400);margin-top:.25rem}
.custom-amount{margin-bottom:1.5rem}
.custom-amount label{display:block;font-size:.85rem;font-weight:600;color:var(--gray-700);margin-bottom:.375rem}
.custom-input{display:flex;align-items:center;border:2px solid var(--gray-200);border-radius:10px;overflow:hidden;transition:border-color .2s}
.custom-input:focus-within{border-color:var(--red)}
.custom-input span{background:var(--gray-50);padding:.75rem 1rem;font-weight:600;color:var(--gray-500);border-right:2px solid var(--gray-200)}
.custom-input input{flex:1;border:none;padding:.75rem 1rem;font-size:1rem;outline:none;font-family:inherit}
.modal-actions{display:flex;flex-direction:column;gap:.75rem}
.modal-actions .btn-primary{padding:.875rem;font-size:1rem}
.modal-disclaimer{font-size:.75rem;color:var(--gray-400);text-align:center;margin-top:1rem}

/* ── Responsive ── */
@media(max-width:1024px){
  .hero .container{grid-template-columns:1fr}
  .hero-visual{display:none}
  .mission-grid{grid-template-columns:1fr}
  .mission-visual{display:none}
  .stats-grid{grid-template-columns:repeat(2,1fr)}
  .involved-grid{grid-template-columns:1fr;max-width:400px;margin:0 auto}
  .news-card{flex:0 0 calc(50% - .75rem)}
  .footer-grid{grid-template-columns:1fr 1fr}
}

@media(max-width:768px){
  .utility-bar{display:none}
  .main-nav{display:none}
  .hamburger{display:flex}
  .hero .container{padding-top:3rem;padding-bottom:3rem}
  .hero h1{font-size:1.75rem}
  .hero-subtitle{font-size:1rem}
  .hero-actions{flex-direction:column}
  .stats-grid{grid-template-columns:1fr;max-width:320px;margin:0 auto}
  .news-card{flex:0 0 calc(100% - 0px);margin-right:0}
  .footer-grid{grid-template-columns:1fr}
  .footer-bottom{flex-direction:column;text-align:center}
  .donate-amounts{grid-template-columns:repeat(2,1fr)}
  .section{padding:3rem 0}
}

/* ── Animations ── */
@keyframes fadeInUp{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:translateY(0)}}
.animate-in{animation:fadeInUp .6s ease forwards}
</style>
</head>
<body>

<!-- Utility Bar -->
<div class="utility-bar">
  <div class="container">
    <a href="#">Sign In</a>
    <a href="#">Contact Us</a>
    <a href="#">Español</a>
  </div>
</div>

<!-- Header / Navigation -->
<header class="site-header">
  <div class="container">
    <a href="#" class="logo">
      <span class="logo-icon">+</span>
      <span>Global Aid Alliance</span>
    </a>
    <nav class="main-nav">
      <a href="#mission">About Us</a>
      <a href="#programs">Disaster Relief</a>
      <a href="#programs">Programs &amp; Services</a>
      <a href="#involved">Volunteer</a>
      <a href="#">Find Local Chapter</a>
      <button class="btn btn-primary" onclick="openDonateModal()">Donate</button>
    </nav>
    <button class="hamburger" id="hamburger" aria-label="Open menu" onclick="toggleMobileMenu()">
      <span></span><span></span><span></span>
    </button>
  </div>
</header>

<!-- Mobile Navigation Drawer -->
<div class="mobile-overlay" id="mobileOverlay" onclick="toggleMobileMenu()"></div>
<nav class="mobile-nav" id="mobileNav">
  <a href="#mission" onclick="toggleMobileMenu()">About Us</a>
  <a href="#programs" onclick="toggleMobileMenu()">Disaster Relief</a>
  <a href="#programs" onclick="toggleMobileMenu()">Programs &amp; Services</a>
  <a href="#involved" onclick="toggleMobileMenu()">Volunteer</a>
  <a href="#" onclick="toggleMobileMenu()">Find Local Chapter</a>
  <a href="#" onclick="toggleMobileMenu()">Sign In</a>
  <a href="#" onclick="toggleMobileMenu()">Contact Us</a>
  <button class="btn btn-primary" onclick="toggleMobileMenu();openDonateModal()">Donate</button>
</nav>

<!-- Hero Section -->
<section class="hero" id="hero">
  <div class="container">
    <div class="hero-text animate-in">
      <span class="hero-badge">Responding to Disasters Since 1947</span>
      <h1>When Disaster Strikes, <span>We're There</span></h1>
      <p class="hero-subtitle">From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.</p>
      <div class="hero-actions">
        <button class="btn btn-white btn-large" onclick="openDonateModal()">Donate Now</button>
        <button class="btn btn-large" style="border:2px solid rgba(255,255,255,.4);color:#fff" onclick="document.getElementById('involved').scrollIntoView({behavior:'smooth'})">Become a Volunteer</button>
      </div>
    </div>
    <div class="hero-visual">
      <div class="hero-card">
        <span class="stat-big" id="heroCounter">0</span>
        <span class="stat-label">People Assisted in 2024</span>
        <div class="hero-card-grid">
          <div><span class="stat-big" style="font-size:1.5rem" id="heroVolunteers">0</span><span class="stat-label">Volunteers</span></div>
          <div><span class="stat-big" style="font-size:1.5rem" id="heroCountries">0</span><span class="stat-label">Countries</span></div>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- Mission Section -->
<section class="section" id="mission">
  <div class="container">
    <div class="section-header">
      <div class="section-label">Our Purpose</div>
      <h2 class="section-title">Guided by Humanity, Driven by Action</h2>
    </div>
    <div class="mission-grid">
      <div class="mission-text">
