<script>
// ── Mobile Menu ──
function toggleMobileMenu() {
  document.getElementById('mobileNav').classList.toggle('open');
  document.getElementById('mobileOverlay').classList.toggle('show');
  document.getElementById('hamburger').classList.toggle('active');
  document.body.style.overflow =
    document.getElementById('mobileNav').classList.contains('open') ? 'hidden' : '';
}

// ── Donate Modal ──
let selectedDonationAmount = null;

function openDonateModal() {
  document.getElementById('donateModal').classList.add('show');
  document.body.style.overflow = 'hidden';
}

function closeDonateModal() {
  document.getElementById('donateModal').classList.remove('show');
  document.body.style.overflow = '';
}

function selectAmount(el) {
  document.querySelectorAll('.donate-amount').forEach(b => b.classList.remove('selected'));
  el.classList.add('selected');
  selectedDonationAmount = el.dataset.amount;
  document.getElementById('selectedAmount').value = selectedDonationAmount;
  document.getElementById('customAmount').value = '';
}

function selectCustomAmount() {
  document.querySelectorAll('.donate-amount').forEach(b => b.classList.remove('selected'));
  const val = document.getElementById('customAmount').value;
  selectedDonationAmount = val;
  document.getElementById('selectedAmount').value = val;
}

document.getElementById('donateModal').addEventListener('click', function(e) {
  if (e.target === this) closeDonateModal();
});

document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') closeDonateModal();
});

// ── Accordion ──
function toggleAccordion(trigger) {
  const item = trigger.parentElement;
  const isActive = item.classList.contains('active');
  // Close all
  document.querySelectorAll('.accordion-item').forEach(i => i.classList.remove('active'));
  // Open clicked (unless it was already open)
  if (!isActive) item.classList.add('active');
}

// ── News Carousel ──
let currentSlide = 0;
let slidesPerView = 3;

function getSlidesPerView() {
  if (window.innerWidth <= 768) return 1;
  if (window.innerWidth <= 1024) return 2;
  return 3;
}

function getTotalSlides() {
  const totalCards = document.querySelectorAll('.news-card').length;
  return Math.max(0, totalCards - getSlidesPerView());
}

function updateCarousel() {
  slidesPerView = getSlidesPerView();
  const track = document.getElementById('newsTrack');
  const cards = document.querySelectorAll('.news-card');
  const cardWidth = cards.length > 0 ? cards[0].offsetWidth + 24 : 0; // 24px gap (1.5rem)
  const offset = currentSlide * cardWidth * -1;
  track.style.transform = `translateX(${offset}px)`;

  // Update dots
  const totalSlides = getTotalSlides() + 1;
  const dotsContainer = document.getElementById('carouselDots');
  dotsContainer.innerHTML = '';
  if (totalSlides > 1) {
    for (let i = 0; i < totalSlides; i++) {
      const dot = document.createElement('div');
      dot.className = 'carousel-dot' + (i === currentSlide ? ' active' : '');
      dot.onclick = function() { goToSlide(i); };
      dotsContainer.appendChild(dot);
    }
  }

  // Update buttons
  document.getElementById('prevBtn').disabled = currentSlide === 0;
  document.getElementById('nextBtn').disabled = currentSlide >= getTotalSlides();
}

function moveCarousel(direction) {
  const totalSlides = getTotalSlides();
  currentSlide = Math.max(0, Math.min(totalSlides, currentSlide + direction));
  updateCarousel();
}

function goToSlide(index) {
  currentSlide = index;
  updateCarousel();
}

// ── Counter Animation ──
function animateCounters() {
  document.querySelectorAll('.counter').forEach(counter => {
    if (counter.dataset.animated) return;
    counter.dataset.animated = 'true';
    const target = parseInt(counter.dataset.target);
    const duration = 2000;
    const start = performance.now();

    function update(now) {
      const elapsed = now - start;
      const progress = Math.min(elapsed / duration, 1);
      // Ease-out cubic
      const eased = 1 - Math.pow(1 - progress, 3);
      const current = Math.round(eased * target);
      counter.textContent = current.toLocaleString();
      if (progress < 1) requestAnimationFrame(update);
    }
    requestAnimationFrame(update);
  });
}

// Intersection Observer for counters
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      animateCounters();
    }
  });
}, { threshold: 0.3 });

document.querySelectorAll('.counter').forEach(el => observer.observe(el));

// Hero counter (always animate on load)
function animateHeroCounters() {
  const heroCounter = document.getElementById('heroCounter');
  const heroVolunteers = document.getElementById('heroVolunteers');
  const heroCountries = document.getElementById('heroCountries');

  [{el: heroCounter, target: 12, suffix: ''},
   {el: heroVolunteers, target: 50, suffix: ''},
   {el: heroCountries, target: 190, suffix: ''}].forEach(({el, target, suffix}) => {
    const duration = 2500;
    const start = performance.now();
    function update(now) {
      const elapsed = now - start;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      const current = Math.round(eased * target);
      el.textContent = current.toLocaleString() + suffix;
      if (progress < 1) requestAnimationFrame(update);
    }
    requestAnimationFrame(update);
  });
}
animateHeroCounters();

// ── Carousel Resize ──
let resizeDebounce;
window.addEventListener('resize', () => {
  clearTimeout(resizeDebounce);
  resizeDebounce = setTimeout(() => {
    currentSlide = Math.min(currentSlide, getTotalSlides());
    updateCarousel();
